ALTER TABLE source_cursor ADD COLUMN last_successful_batch varchar(14);
UPDATE source_cursor SET last_successful_batch=(SELECT max(batch_id) FROM gdelt_batch WHERE status='SUCCESS') WHERE source_id='GDELT';
ALTER TABLE gdelt_batch ADD COLUMN discovery_kind varchar(20) NOT NULL DEFAULT 'REALTIME';
ALTER TABLE gdelt_batch ADD COLUMN availability varchar(40) NOT NULL DEFAULT 'PUBLISHED_NOT_AVAILABLE';
ALTER TABLE gdelt_batch ADD COLUMN retry_at timestamptz;
ALTER TABLE gdelt_batch ADD COLUMN attempts integer NOT NULL DEFAULT 0;
UPDATE gdelt_batch SET availability='AVAILABLE' WHERE status='SUCCESS';
CREATE TABLE gdelt_index_observation(id bigserial PRIMARY KEY, url text NOT NULL, fetched_at timestamptz NOT NULL DEFAULT now(), sha256 char(64) NOT NULL, raw_latest bytea, bytes bigint NOT NULL, records integer NOT NULL);
CREATE TABLE gdelt_gap(batch_id varchar(14) PRIMARY KEY, state varchar(40) NOT NULL DEFAULT 'NOT_PUBLISHED', first_checked_at timestamptz NOT NULL DEFAULT now(), last_checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE collector_lease(source_id varchar(20) PRIMARY KEY REFERENCES source_registry(id), owner uuid NOT NULL, acquired_at timestamptz NOT NULL DEFAULT now(), heartbeat_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE TABLE domain_budget(domain text PRIMARY KEY, next_at timestamptz NOT NULL DEFAULT now(), cooldown_until timestamptz, window_started timestamptz NOT NULL DEFAULT now(), requests integer NOT NULL DEFAULT 0);
ALTER TABLE ingestion_job ADD COLUMN heartbeat_at timestamptz;
ALTER TABLE http_request_observation ADD COLUMN failure_kind varchar(40);
ALTER TABLE ingestion_quarantine ADD COLUMN anomaly_level varchar(20) NOT NULL DEFAULT 'REQUEST';
CREATE TABLE evidence_provenance(evidence_id uuid PRIMARY KEY REFERENCES raw_evidence(id), original_source_url text NOT NULL, canonical_source_url text NOT NULL, redirect_final_url text, canonical_equivalence_confirmed boolean NOT NULL DEFAULT false, source_identity varchar(30) NOT NULL, integrity varchar(30) NOT NULL DEFAULT 'HASH_CONFIRMED', fact_verification varchar(30) NOT NULL DEFAULT 'PENDING', independent_verification varchar(30) NOT NULL DEFAULT 'PENDING');
INSERT INTO evidence_provenance(evidence_id,original_source_url,canonical_source_url,source_identity) SELECT r.id,r.source_url,replace(r.source_url,'europa.eu//','europa.eu/'),CASE WHEN s.level='L0' THEN 'OFFICIAL_SOURCE_CONFIRMED' ELSE 'AGGREGATOR_CONFIRMED' END FROM raw_evidence r JOIN source_registry s ON s.id=r.source_id;
CREATE FUNCTION record_evidence_provenance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN INSERT INTO evidence_provenance(evidence_id,original_source_url,canonical_source_url,source_identity) SELECT NEW.id,NEW.source_url,replace(NEW.source_url,'europa.eu//','europa.eu/'),CASE WHEN level='L0' THEN 'OFFICIAL_SOURCE_CONFIRMED' ELSE 'AGGREGATOR_CONFIRMED' END FROM source_registry WHERE id=NEW.source_id; RETURN NEW; END $$;
CREATE TRIGGER evidence_provenance_insert AFTER INSERT ON raw_evidence FOR EACH ROW EXECUTE FUNCTION record_evidence_provenance();
ALTER TABLE stream_delivery ADD COLUMN failure_kind varchar(40);
ALTER TABLE stream_delivery ADD COLUMN replay boolean NOT NULL DEFAULT false;
CREATE TABLE stream_connection(id uuid PRIMARY KEY, opened_at timestamptz NOT NULL DEFAULT now(), last_activity_at timestamptz NOT NULL DEFAULT now(), initial_cursor bigint NOT NULL, replay_ceiling bigint NOT NULL, closed_at timestamptz, close_kind varchar(40));
CREATE TABLE monitor_alert(key text PRIMARY KEY, source text NOT NULL, message text NOT NULL, state varchar(10) NOT NULL, opened_at timestamptz NOT NULL DEFAULT now(), last_seen_at timestamptz NOT NULL DEFAULT now(), recovered_at timestamptz, occurrences integer NOT NULL DEFAULT 1);
CREATE TABLE sec_filing_cursor(cik char(10) PRIMARY KEY, last_accession text, last_accepted_at timestamptz, checked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fred_observation(evidence_id uuid PRIMARY KEY REFERENCES raw_evidence(id), series_id text NOT NULL, series_title text NOT NULL, units text NOT NULL, observation_date date NOT NULL, value numeric, missing boolean NOT NULL, realtime_start date NOT NULL, realtime_end date NOT NULL, availability_time timestamptz, acquired_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fred_series(series_id text PRIMARY KEY, title text NOT NULL, units text NOT NULL, raw_response bytea NOT NULL, sha256 char(64) NOT NULL CHECK(sha256=encode(sha256(raw_response),'hex')), acquired_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX gdelt_retry_queue ON gdelt_batch(status,retry_at,batch_id);
CREATE INDEX stream_delivery_ack ON stream_delivery(outbox_id,acknowledged_at) WHERE outcome='SENT';
ALTER TABLE raw_evidence ALTER COLUMN ingested_at SET DEFAULT clock_timestamp();
ALTER TABLE stream_outbox ALTER COLUMN created_at SET DEFAULT clock_timestamp();
CREATE FUNCTION classify_http_observation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.failure_kind IS NULL THEN NEW.failure_kind=CASE WHEN NEW.status=304 THEN 'NOT_MODIFIED' WHEN NEW.status=403 THEN 'HTTP_403' WHEN NEW.status=404 THEN 'HTTP_404' WHEN NEW.status=429 THEN 'HTTP_429' WHEN NEW.status>=500 THEN 'HTTP_5XX' WHEN NEW.status IS NULL AND NEW.error IS NOT NULL THEN 'TRANSPORT_FAILURE' ELSE NULL END; END IF; RETURN NEW; END $$;
CREATE TRIGGER classify_http BEFORE INSERT ON http_request_observation FOR EACH ROW EXECUTE FUNCTION classify_http_observation();
